aggregation.command:
{ $graphLookup: {
  from: 'employees',
  startWith: '$reportsTo',
  connectFromField: 'reportsTo',
  connectToField: '_id',
  as: 'chain',
  maxDepth: 5
} }

aggregation.example:
Model.aggregate([
 { $graphLookup: {
   from: 'refs',
   startWith: '$userId',
   connectFromField: 'userId',
   connectToField: 'referredBy',
   as: 'network'
 } }
])

aggregation.command:
{ $bucket: {
  groupBy: '$price',
  boundaries: [0, 50, 100, 200],
  default: '200+',
  output: { count: { $sum: 1 }, titles: { $push: '$title' } }
} }

aggregation.example:
Model.aggregate([
 { $bucket: {
   groupBy: '$score',
   boundaries: [0, 60, 80, 100],
   default: 'other',
   output: { n: { $sum: 1 } }
 } }
])

expressions.command:
{ $switch: { branches: [
  { case: { $eq: [ '$status', 'A' ] }, then: 1 },
  { case: { $eq: [ '$status', 'B' ] }, then: 2 }
], default: 0 } }

expressions.example:
Model.aggregate([
 { $project: {
   code: { $switch: {
     branches: [
       { case: { $lt: [ '$score', 60 ] }, then: 'F' },
       { case: { $lt: [ '$score', 80 ] }, then: 'C' }
     ],
     default: 'A'
   } }
 } }
])
